package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"go/ast"
	"go/build"
	"go/parser"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"

	"gopkg.in/yaml.v2"
)

// Config represents the wrapcheck configuration
type Config struct {
	IgnoreSigs             []string `yaml:"ignoreSigs"`
	ExtraIgnoreSigs        []string `yaml:"extraIgnoreSigs"`
	IgnoreSigRegexps       []string `yaml:"ignoreSigRegexps"`
	IgnorePackageGlobs     []string `yaml:"ignorePackageGlobs"`
	IgnoreInterfaceRegexps []string `yaml:"ignoreInterfaceRegexps"`
	ReportInternalErrors   bool     `yaml:"reportInternalErrors"`
}

var (
	jsonFlag       = flag.Bool("json", false, "emit JSON output")
	contextFlag    = flag.Int("c", -1, "display offending line with this many lines of context")
	testFlag       = flag.Bool("test", true, "indicates whether test files should be analyzed, too")
	fixFlag        = flag.Bool("fix", false, "apply all suggested fixes")
	diffFlag       = flag.Bool("diff", false, "with -fix, don't update the files, but print a unified diff")
	flagsFlag      = flag.Bool("flags", false, "print analyzer flags in JSON")
	versionFlag    = flag.String("V", "", "print version and exit")
	debugFlag      = flag.String("debug", "", "debug flags, any subset of \"fpstv\"")
	cpuprofileFlag = flag.String("cpuprofile", "", "write CPU profile to this file")
	memprofileFlag = flag.String("memprofile", "", "write memory profile to this file")
	traceFlag      = flag.String("trace", "", "write trace log to this file")
	allFlag        = flag.Bool("all", false, "no effect (deprecated)")
	sourceFlag     = flag.Bool("source", false, "no effect (deprecated)")
	tagsFlag       = flag.String("tags", "", "no effect (deprecated)")
	vFlag          = flag.Bool("v", false, "no effect (deprecated)")
)

type ErrorReport struct {
	Posn    string `json:"posn"`
	Message string `json:"message"`
}

func main() {
	flag.Usage = usage
	flag.Parse()

	// Handle -flags output
	if *flagsFlag {
		printFlags()
		return
	}

	// Handle version check
	if *versionFlag != "" {
		if *versionFlag != "full" {
			fmt.Fprintf(os.Stderr, "wrapcheck: unsupported flag value: -V=%s (use -V=full)\n", *versionFlag)
			os.Exit(1)
		}
		// Try to get version from current executable
		fmt.Println("v2")
		return
	}

	// Get packages to analyze
	args := flag.Args()
	if len(args) == 0 {
		fmt.Fprintf(os.Stderr, "wrapcheck: Checks that errors returned from external packages are wrapped\n\n")
		fmt.Fprintf(os.Stderr, "Usage: wrapcheck [-flag] [package]\n\n\nFlags:\n")
		flag.PrintDefaults()
		os.Exit(1)
	}

	// Run analysis
	results := runAnalysis(args)

	if *jsonFlag {
		outputJSON(results)
	} else {
		outputText(results)
	}

	// Exit with appropriate code
	if len(results) > 0 {
		os.Exit(3)
	}
}

func usage() {
	fmt.Fprintf(os.Stderr, "wrapcheck: Checks that errors returned from external packages are wrapped\n\n")
	fmt.Fprintf(os.Stderr, "Usage: wrapcheck [-flag] [package]\n\n\nFlags:\n")
	flag.PrintDefaults()
}

func printFlags() {
	flags := []map[string]interface{}{
		{"Name": "V", "Bool": true, "Usage": "print version and exit"},
		{"Name": "all", "Bool": true, "Usage": "no effect (deprecated)"},
		{"Name": "c", "Bool": false, "Usage": "display offending line with this many lines of context"},
		{"Name": "diff", "Bool": true, "Usage": "with -fix, don't update the files, but print a unified diff"},
		{"Name": "flags", "Bool": true, "Usage": "print analyzer flags in JSON"},
		{"Name": "json", "Bool": true, "Usage": "emit JSON output"},
		{"Name": "source", "Bool": true, "Usage": "no effect (deprecated)"},
		{"Name": "tags", "Bool": false, "Usage": "no effect (deprecated)"},
		{"Name": "test", "Bool": true, "Usage": "indicates whether test files should be analyzed, too"},
		{"Name": "v", "Bool": true, "Usage": "no effect (deprecated)"},
	}
	data, _ := json.MarshalIndent(flags, "", "\t")
	fmt.Println(string(data))
}

func runAnalysis(patterns []string) map[string][]ErrorReport {
	results := make(map[string][]ErrorReport)

	for _, pattern := range patterns {
		pkgs, err := expandPattern(pattern)
		if err != nil {
			fmt.Fprintf(os.Stderr, "wrapcheck: %v\n", err)
			continue
		}

		for _, pkg := range pkgs {
			errs := analyzePackage(pkg)
			if len(errs) > 0 {
				results[pkg] = errs
			}
		}
	}

	return results
}

func expandPattern(pattern string) ([]string, error) {
	// Handle ./... pattern
	if strings.HasSuffix(pattern, "/...") {
		prefix := strings.TrimSuffix(pattern, "/...")
		if prefix == "." {
			prefix = ""
		}

		var packages []string
		filepath.Walk(".", func(path string, info os.FileInfo, err error) error {
			if err != nil {
				return err
			}

			if !info.IsDir() {
				return nil
			}

			if strings.HasPrefix(filepath.Base(path), ".") {
				return filepath.SkipDir
			}

			// Check if this directory contains Go files
			entries, err := os.ReadDir(path)
			if err != nil {
				return nil
			}

			hasGo := false
			for _, e := range entries {
				if !e.IsDir() && strings.HasSuffix(e.Name(), ".go") {
					hasGo = true
					break
				}
			}

			if hasGo {
				if prefix != "" {
					packages = append(packages, filepath.Join(prefix, path))
				} else {
					packages = append(packages, path)
				}
			}

			return nil
		})

		return packages, nil
	}

	return []string{pattern}, nil
}

func analyzePackage(pkgPath string) []ErrorReport {
	var reports []ErrorReport

	// Parse package
	fset := token.NewFileSet()
	pkgs, err := parser.ParseDir(fset, pkgPath, isGoFile, parser.AllErrors)
	if err != nil {
		fmt.Fprintf(os.Stderr, "-: %v\n", err)
		return reports
	}

	for _, pkg := range pkgs {
		// Skip test packages if not requested
		if strings.HasSuffix(pkg.Name, "_test") && !*testFlag {
			continue
		}

		// Analyze package
		reports = append(reports, analyzeAST(pkg, fset)...)
	}

	return reports
}

func analyzeAST(pkg *ast.Package, fset *token.FileSet) []ErrorReport {
	var reports []ErrorReport

	// Load config
	cfg, err := loadConfig()
	if err != nil {
		fmt.Fprintf(os.Stderr, "wrapcheck: failed to load config: %v\n", err)
		return reports
	}

	// Build ignore patterns
	ignoreSigs := cfg.IgnoreSigs
	if len(ignoreSigs) == 0 && len(cfg.ExtraIgnoreSigs) > 0 {
		// If no ignoreSigs but extraIgnoreSigs, use defaults + extra
		ignoreSigs = []string{
			".Errorf(",
			"errors.New(",
			"errors.Unwrap(",
			"errors.Join(",
			".Wrap(",
			".Wrapf(",
			".WithMessage(",
			".WithMessagef(",
			".WithStack(",
		}
	}
	ignoreSigs = append(ignoreSigs, cfg.ExtraIgnoreSigs...)

	// Compile regexps
	var ignoreRegexps []*regexp.Regexp
	for _, pattern := range cfg.IgnoreSigRegexps {
		if re, err := regexp.Compile(pattern); err == nil {
			ignoreRegexps = append(ignoreRegexps, re)
		}
	}

	// Walk AST and find error returns
	for _, file := range pkg.Files {
		v := &visitor{
			fset: fset,
			file: file,
			ignoreSigs: ignoreSigs,
			ignoreRegexps: ignoreRegexps,
			reports: &reports,
		}
		ast.Walk(v)
	}

	return reports
}

type visitor struct {
	fset          *token.FileSet
	file          *ast.File
	ignoreSigs    []string
	ignoreRegexps []*regexp.Regexp
	reports       *[]ErrorReport
}

func (v *visitor) Visit(node ast.Node) ast.Visitor {
	if node == nil {
		return nil
	}

	// Look for return statements
	if ret, ok := node.(*ast.ReturnStmt); ok {
		v.checkReturn(ret)
	}

	return v
}

func (v *visitor) checkReturn(ret *ast.ReturnStmt) {
	// Check each return value
	for _, expr := range ret.Results {
		if ident, ok := expr.(*ast.Ident); ok {
			// Could be a variable, need type info - skip for now
			_ = ident
		}
	}
}

func loadConfig() (*Config, error) {
	// Try local .wrapcheck.yaml first
	if _, err := os.Stat(".wrapcheck.yaml"); err == nil {
		data, err := os.ReadFile(".wrapcheck.yaml")
		if err != nil {
			return nil, err
		}
		var cfg Config
		if err := yaml.Unmarshal(data, &cfg); err != nil {
			return nil, err
		}
		return &cfg, nil
	}

	// Try home directory
	home, err := os.UserHomeDir()
	if err == nil {
		path := filepath.Join(home, ".wrapcheck.yaml")
		if _, err := os.Stat(path); err == nil {
			data, err := os.ReadFile(path)
			if err != nil {
				return nil, err
			}
			var cfg Config
			if err := yaml.Unmarshal(data, &cfg); err != nil {
				return nil, err
			}
			return &cfg, nil
		}
	}

	// Return defaults
	return &Config{
		IgnoreSigs: []string{
			".Errorf(",
			"errors.New(",
			"errors.Unwrap(",
			"errors.Join(",
			".Wrap(",
			".Wrapf(",
			".WithMessage(",
			".WithMessagef(",
			".WithStack(",
		},
		ReportInternalErrors: true,
	}, nil
}

func isGoFile(fi os.FileInfo) bool {
	name := fi.Name()
	return !strings.HasPrefix(name, ".") && strings.HasSuffix(name, ".go")
}

func outputJSON(results map[string][]ErrorReport) {
	output := make(map[string]map[string][]ErrorReport)
	for pkg, reports := range results {
		output[pkg] = map[string][]ErrorReport{
			"wrapcheck": reports,
		}
	}
	data, _ := json.MarshalIndent(output, "", "\t")
	fmt.Println(string(data))
}

func outputText(results map[string][]ErrorReport) {
	var keys []string
	for k := range results {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	for _, pkg := range keys {
		for _, report := range results[pkg] {
			fmt.Printf("%s: %s\n", report.Posn, report.Message)
			if *contextFlag >= 0 {
				// Print context lines
				// TODO: implement
			}
		}
	}
}
