	pkgs, err := parser.ParseDir(fset, dirPath, goFileFilter, parser.AllErrors)
	if err != nil {
		return nil, fmt.Errorf("-: %v", err)
	}

	if len(pkgs) == 0 {
		return nil, fmt.Errorf("wrapcheck: %s matched no packages", dirPath)
	}

	// Load configuration
	cfg, _ := loadConfig()

	for pkgName, pkg := range pkgs {
		// Skip test packages if not requested
		if strings.HasSuffix(pkgName, "_test") && !*testFlag {
			continue
		}

		// Analyze the package
		reports := analyzePackageAST(pkg, fset, dirPath, cfg)
		if len(reports) > 0 {
			results[pkgName] = reports
		}
	}

	return results, nil
}

func analyzePackageAST(pkg *ast.Package, fset *token.FileSet, dirPath string, cfg *Config) []ErrorReport {
	var reports []ErrorReport

	// Build ignore patterns
	ignoreSigs := cfg.IgnoreSigs
	if len(ignoreSigs) == 0 && len(cfg.ExtraIgnoreSigs) > 0 {
		ignoreSigs = []string{
			".Errorf(",
			"errors.New(",
			"errors.Unwrap(",
			"errors.Join(",
			".Wrap(",
			".Wrapf(",
			".WithMessage(",
			".WithMessagef(",
			".WithStack(",
		}
	}
	ignoreSigs = append(ignoreSigs, cfg.ExtraIgnoreSigs...)

	// Compile regexps
	var ignoreRegexps []*regexp.Regexp
	for _, pattern := range cfg.IgnoreSigRegexps {
		if re, err := regexp.Compile(pattern); err == nil {
			ignoreRegexps = append(ignoreRegexps, re)
		}
	}

	// Walk AST
	for _, file := range pkg.Files {
		v := &astVisitor{
			fset: fset,
			file: file,
			pkg: pkg,
			ignoreSigs: ignoreSigs,
			ignoreRegexps: ignoreRegexps,
			reports: &reports,
		}
		ast.Walk(v)
	}

	return reports
}

type astVisitor struct {
	fset          *token.FileSet
	file          *ast.File
	pkg           *ast.Package
	ignoreSigs    []string
	ignoreRegexps []*regexp.Regexp
	reports       *[]ErrorReport
}

func (v *astVisitor) Visit(node ast.Node) ast.Visitor {
	if node == nil {
		return nil
	}

	// Look for function declarations to analyze their bodies
	switch n := node.(type) {
	case *ast.FuncDecl:
		if n.Body != nil {
			v.analyzeFuncBody(n.Body)
		}
	case *ast.FuncLit:
		if n.Body != nil {
			v.analyzeFuncBody(n.Body)
		}
	}

	return v
}

func (v *astVisitor) analyzeFuncBody(body *ast.BlockStmt) {
	for _, stmt := range body.List {
		v.analyzeStmt(stmt)
	}
}

func (v *astVisitor) analyzeStmt(stmt ast.Stmt) {
	if stmt == nil {
		return
	}

	switch s := stmt.(type) {
	case *ast.ReturnStmt:
		v.checkReturnStmt(s)
	case *ast.IfStmt:
		if s.Body != nil {
			v.analyzeFuncBody(s.Body)
		}
		if s.Else != nil {
			v.analyzeStmt(s.Else)
		}
	case *ast.BlockStmt:
		v.analyzeFuncBody(s)
	case *ast.ForStmt:
		if s.Body != nil {
			v.analyzeFuncBody(s.Body)
		}
	case *ast.RangeStmt:
		if s.Body != nil {
			v.analyzeFuncBody(s.Body)
		}
	case *ast.SwitchStmt:
		if s.Body != nil {
			v.analyzeFuncBody(s.Body)
		}
	case *ast.TypeSwitchStmt:
		if s.Body != nil {
			v.analyzeFuncBody(s.Body)
		}
	case *ast.SelectStmt:
		if s.Body != nil {
			v.analyzeFuncBody(s.Body)
		}
	}
}

func (v *astVisitor) checkReturnStmt(ret *ast.ReturnStmt) {
	for _, expr := range ret.Results {
		v.checkExpr(expr)
	}
}

func (v *astVisitor) checkExpr(expr ast.Expr) {
	if expr == nil {
		return
	}

	// Check for calls to external functions returning unwrapped errors
	switch e := expr.(type) {
	case *ast.CallExpr:
		v.checkCall(e)
	case *ast.Ident:
		// Variables - would need type info to track
	}
}

func (v *astVisitor) checkCall(call *ast.CallExpr) {
	// Get the function name
	funcName := getFuncName(call.Fun)
	if funcName == "" {
		return
	}

	// Check if this function is in the ignore list
	if v.isIgnored(funcName) {
		return
	}

	// Check if this is an external package function
	if v.isExternalFunc(funcName) {
		pos := v.fset.Position(call.Pos())
		msg := fmt.Sprintf("error returned from external package is unwrapped: sig: func %s(...) error", funcName)
		*v.reports = append(*v.reports, ErrorReport{
			Posn:    fmt.Sprintf("%s:%d:%d", pos.Filename, pos.Line, pos.Column),
			Message: msg,
		})
	}
}

func (v *astVisitor) isIgnored(funcName string) bool {
	// Check against ignore sigs
	for _, sig := range v.ignoreSigs {
		if strings.Contains(funcName, sig) {
			return true
		}
	}

	// Check against regexps
	for _, re := range v.ignoreRegexps {
		if re.MatchString(funcName) {
			return true
		}
	}

	return false
}

func (v *astVisitor) isExternalFunc(funcName string) bool {
	// External means from a package that's not the current package
	// Check if it has a package qualifier
	parts := strings.Split(funcName, ".")
	if len(parts) < 2 {
		// Local function call, not external
		return false
	}

	// If it starts with a capital letter or contains a slash, it's likely external
	// For now, assume anything with a dot is external (package.Function)
	return true
}

func getFuncName(expr ast.Expr) string {
	switch e := expr.(type) {
	case *ast.SelectorExpr:
		// e.X.e.Sel
		prefix := getFuncName(e.X)
		if prefix != "" {
			return prefix + "." + e.Sel.Name
		}
		return e.Sel.Name
	case *ast.Ident:
		return e.Name
	}
	return ""
}

func goFileFilter(info os.FileInfo) bool {
	name := info.Name()
	if strings.HasPrefix(name, ".") {
		return false
	}
	return strings.HasSuffix(name, ".go")
}

func loadConfig() (*Config, error) {
	// Try local .wrapcheck.yaml first
	cfg, err := loadYAML(".wrapcheck.yaml")
	if err == nil {
		return cfg, nil
	}

	// Try home directory
	home, err := os.UserHomeDir()
	if err == nil {
		path := filepath.Join(home, ".wrapcheck.yaml")
		cfg, err := loadYAML(path)
		if err == nil {
			return cfg, nil
		}
	}

	// Return defaults
	return &Config{
		IgnoreSigs: []string{
			".Errorf(",
			"errors.New(",
			"errors.Unwrap(",
			"errors.Join(",
			".Wrap(",
			".Wrapf(",
			".WithMessage(",
			".WithMessagef(",
			".WithStack(",
		},
		ReportInternalErrors: true,
	}, nil
}

func loadYAML(path string) (*Config, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}

	cfg := &Config{
		ReportInternalErrors: true,
	}

	// Simple YAML parsing
	scanner := bufio.NewScanner(strings.NewReader(string(data)))
	var currentKey string
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		if strings.HasSuffix(line, ":") {
			currentKey = strings.TrimSuffix(line, ":")
			continue
		}

		if strings.HasPrefix(line, "- ") {
			value := strings.TrimPrefix(line, "- ")
			value = strings.Trim(value, "\"'")

			switch currentKey {
			case "ignoreSigs":
				cfg.IgnoreSigs = append(cfg.IgnoreSigs, value)
			case "extraIgnoreSigs":
				cfg.ExtraIgnoreSigs = append(cfg.ExtraIgnoreSigs, value)
			case "ignoreSigRegexps":
				cfg.IgnoreSigRegexps = append(cfg.IgnoreSigRegexps, value)
			case "ignorePackageGlobs":
				cfg.IgnorePackageGlobs = append(cfg.IgnorePackageGlobs, value)
			case "ignoreInterfaceRegexps":
				cfg.IgnoreInterfaceRegexps = append(cfg.IgnoreInterfaceRegexps, value)
			}
		} else if strings.Contains(line, ":") {
			parts := strings.SplitN(line, ":", 2)
			key := strings.TrimSpace(parts[0])
			value := strings.TrimSpace(parts[1])
			value = strings.Trim(value, "\"'")

			if key == "reportInternalErrors" {
				cfg.ReportInternalErrors = value == "true"
			}
		}
	}

	return cfg, nil
}

func outputJSON(results map[string][]ErrorReport) {
	output := make(map[string]map[string][]ErrorReport)
	for pkg, reports := range results {
		output[pkg] = map[string][]ErrorReport{
			"wrapcheck": reports,
		}
	}
	data, _ := json.MarshalIndent(output, "", "\t")
	fmt.Println(string(data))
}

func outputText(results map[string][]ErrorReport) {
	var keys []string
	for k := range results {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	for _, pkg := range keys {
		for _, report := range results[pkg] {
			fmt.Printf("%s: %s\n", report.Posn, report.Message)

			if *contextFlag >= 0 {
				// Print context lines
				printContext(report.Posn)
			}
		}
	}
}

func printContext(posn string) {
	// Parse position like "/path/to/file.go:12:15"
	parts := strings.Split(posn, ":")
	if len(parts) < 3 {
		return
	}

	filename := parts[0]
	lineNum, _ := strconv.Atoi(parts[1])

	// Read file and print context
	data, err := os.ReadFile(filename)
	if err != nil {
		return
	}

	lines := strings.Split(string(data), "\n")
	start := lineNum - *contextFlag - 1
	if start < 0 {
		start = 0
	}
	end := lineNum + *contextFlag
	if end > len(lines) {
		end = len(lines)
	}

	for i := start; i < end; i++ {
		if i < len(lines) {
			fmt.Printf("\t%d\t%s\n", i+1, lines[i])
		}
	}
}
