package main

import (
	"bufio"
	"encoding/json"
	"flag"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

// Config represents the wrapcheck configuration
type Config struct {
	IgnoreSigs             []string
	ExtraIgnoreSigs        []string
	IgnoreSigRegexps       []string
	IgnorePackageGlobs     []string
	IgnoreInterfaceRegexps []string
	ReportInternalErrors   bool
}

type ErrorReport struct {
	Posn    string `json:"posn"`
	Message string `json:"message"`
}

var (
	jsonFlag       = flag.Bool("json", false, "emit JSON output")
	contextFlag    = flag.Int("c", -1, "display offending line with this many lines of context")
	testFlag       = flag.Bool("test", true, "indicates whether test files should be analyzed, too")
	fixFlag        = flag.Bool("fix", false, "apply all suggested fixes")
	diffFlag       = flag.Bool("diff", false, "with -fix, don't update the files, but print a unified diff")
	flagsFlag      = flag.Bool("flags", false, "print analyzer flags in JSON")
	versionFlag    = flag.String("V", "", "print version and exit")
	debugFlag      = flag.String("debug", "", "debug flags, any subset of \"fpstv\"")
