package main

import (
	"bufio"
	"encoding/json"
	"flag"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

// Config represents the wrapcheck configuration
type Config struct {
	IgnoreSigs             []string
	ExtraIgnoreSigs        []string
	IgnoreSigRegexps       []string
	IgnorePackageGlobs     []string
	IgnoreInterfaceRegexps []string
	ReportInternalErrors   bool
}

type ErrorReport struct {
	Posn    string `json:"posn"`
	Message string `json:"message"`
}

// CallInfo tracks where a variable came from
type CallInfo struct {
	FuncName string
}

var (
	jsonFlag       = flag.Bool("json", false, "emit JSON output")
	contextFlag    = flag.Int("c", -1, "display offending line with this many lines of context")
	testFlag       = flag.Bool("test", true, "indicates whether test files should be analyzed, too")
	fixFlag        = flag.Bool("fix", false, "apply all suggested fixes")
	diffFlag       = flag.Bool("diff", false, "with -fix, don't update the files, but print a unified diff")
	flagsFlag      = flag.Bool("flags", false, "print analyzer flags in JSON")
	versionFlag    = flag.String("V", "", "print version and exit")
	debugFlag      = flag.String("debug", "", "debug flags, any subset of \"fpstv\"")
	cpuprofileFlag = flag.String("cpuprofile", "", "write CPU profile to this file")
	memprofileFlag = flag.String("memprofile", "", "write memory profile to this file")
	traceFlag      = flag.String("trace", "", "write trace log to this file")
	allFlag        = flag.Bool("all", false, "no effect (deprecated)")
	sourceFlag     = flag.Bool("source", false, "no effect (deprecated)")
	tagsFlag       = flag.String("tags", "", "no effect (deprecated)")
	vFlag          = flag.Bool("v", false, "no effect (deprecated)")
)

func main() {
	flag.Usage = usage
	flag.Parse()

	// Handle -flags output
	if *flagsFlag {
		printFlags()
		return
	}

	// Handle version check
	if *versionFlag != "" {
		if *versionFlag != "full" {
			fmt.Fprintf(os.Stderr, "wrapcheck: unsupported flag value: -V=%s (use -V=full)\n", *versionFlag)
			os.Exit(1)
		}
		fmt.Println("v2")
		return
	}

	// Get packages to analyze
	args := flag.Args()
	if len(args) == 0 {
		fmt.Fprintf(os.Stderr, "wrapcheck: Checks that errors returned from external packages are wrapped\n\n")
		fmt.Fprintf(os.Stderr, "Usage: wrapcheck [-flag] [package]\n\n\nFlags:\n")
		flag.PrintDefaults()
		os.Exit(1)
	}

	// Run analysis  
	allReports := make(map[string][]ErrorReport)
	hasErrors := false

	for _, pattern := range args {
		reports, err := analyzePattern(pattern)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%v\n", err)
			hasErrors = true
			continue
		}
		for k, v := range reports {
			allReports[k] = v
		}
	}

	if *jsonFlag {
		outputJSON(allReports)
	} else {
		outputText(allReports)
	}

	// Exit with appropriate code
	if len(allReports) > 0 {
		os.Exit(3)
	}
	if hasErrors {
		os.Exit(1)
	}
}

func usage() {
	fmt.Fprintf(os.Stderr, "wrapcheck: Checks that errors returned from external packages are wrapped\n\n")
	fmt.Fprintf(os.Stderr, "Usage: wrapcheck [-flag] [package]\n\n\nFlags:\n")
	flag.PrintDefaults()
}

func printFlags() {
	flags := []map[string]interface{}{
		{"Name": "V", "Bool": true, "Usage": "print version and exit"},
		{"Name": "all", "Bool": true, "Usage": "no effect (deprecated)"},
		{"Name": "c", "Bool": false, "Usage": "display offending line with this many lines of context"},
		{"Name": "diff", "Bool": true, "Usage": "with -fix, don't update the files, but print a unified diff"},
		{"Name": "flags", "Bool": true, "Usage": "print analyzer flags in JSON"},
		{"Name": "json", "Bool": true, "Usage": "emit JSON output"},
		{"Name": "source", "Bool": true, "Usage": "no effect (deprecated)"},
		{"Name": "tags", "Bool": false, "Usage": "no effect (deprecated)"},
		{"Name": "test", "Bool": true, "Usage": "indicates whether test files should be analyzed, too"},
		{"Name": "v", "Bool": true, "Usage": "no effect (deprecated)"},
	}
	data, _ := json.MarshalIndent(flags, "", "\t")
	fmt.Println(string(data))
}

func analyzePattern(pattern string) (map[string][]ErrorReport, error) {
	results := make(map[string][]ErrorReport)

	// Handle ./... pattern
	if strings.HasSuffix(pattern, "/...") {
		packages := expandPattern(pattern)
		for _, pkg := range packages {
			reports, _ := analyzeDir(pkg)
			for k, v := range reports {
				results[k] = v
			}
		}
		return results, nil
	}

	reports, err := analyzeDir(pattern)
	if err != nil {
		return nil, err
	}
	return reports, nil
}

func expandPattern(pattern string) []string {
	prefix := strings.TrimSuffix(pattern, "/...")
	if prefix == "." {
		prefix = ""
	}

	var packages []string
	filepath.Walk(".", func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		if !info.IsDir() {
			return nil
		}

		if strings.HasPrefix(filepath.Base(path), ".") && path != "." {
			return filepath.SkipDir
		}

		// Check if this directory contains Go files
		entries, err := os.ReadDir(path)
		if err != nil {
			return nil
		}

		hasGoFiles := false
		for _, e := range entries {
			if !e.IsDir() && strings.HasSuffix(e.Name(), ".go") {
				if *testFlag || !strings.HasSuffix(e.Name(), "_test.go") {
					hasGoFiles = true
					break
				}
			}
		}

		if hasGoFiles {
			if prefix != "" {
				packages = append(packages, filepath.Join(prefix, path))
			} else {
				packages = append(packages, path)
			}
		}

		return nil
	})

	return packages
}

func analyzeDir(dirPath string) (map[string][]ErrorReport, error) {
	results := make(map[string][]ErrorReport)

	// Parse directory
	fset := token.NewFileSet()
	pkgs, err := parser.ParseDir(fset, dirPath, goFileFilter, parser.AllErrors)
	if err != nil {
		return nil, fmt.Errorf("-: %v", err)
	}

	if len(pkgs) == 0 {
		return nil, fmt.Errorf("wrapcheck: %s matched no packages", dirPath)
	}

	// Load configuration
	cfg, _ := loadConfig()

	for pkgName, pkg := range pkgs {
		// Skip test packages if not requested
		if strings.HasSuffix(pkgName, "_test") && !*testFlag {
			continue
		}

		// Analyze the package
		reports := analyzePackageAST(pkg, fset, dirPath, cfg)
		if len(reports) > 0 {
			results[pkgName] = reports
		}
	}

	return results, nil
}

func analyzePackageAST(pkg *ast.Package, fset *token.FileSet, dirPath string, cfg *Config) []ErrorReport {
	var reports []ErrorReport

	// Build ignore patterns
	ignoreSigs := cfg.IgnoreSigs
	if len(ignoreSigs) == 0 && len(cfg.ExtraIgnoreSigs) > 0 {
		ignoreSigs = []string{
			".Errorf(",
			"errors.New(",
			"errors.Unwrap(",
			"errors.Join(",
			".Wrap(",
			".Wrapf(",
			".WithMessage(",
			".WithMessagef(",
			".WithStack(",
		}
	}
	ignoreSigs = append(ignoreSigs, cfg.ExtraIgnoreSigs...)

	// Compile regexps
	var ignoreRegexps []*regexp.Regexp
	for _, pattern := range cfg.IgnoreSigRegexps {
		if re, err := regexp.Compile(pattern); err == nil {
			ignoreRegexps = append(ignoreRegexps, re)
		}
	}

	// Build a map of all external function calls and their sources
	externalCalls := make(map[string]*CallInfo) // variable -> CallInfo

	// First pass: identify all external calls
	for _, file := range pkg.Files {
		identifyExternalCalls(file, externalCalls)
	}

	// Second pass: check returns for external errors
	for _, file := range pkg.Files {
		checkReturns(file, fset, externalCalls, ignoreSigs, ignoreRegexps, &reports)
	}

	return reports
}

// identifyExternalCalls builds a map of variable names that hold results from external calls
func identifyExternalCalls(file *ast.File, externalCalls map[string]*CallInfo) {
	ast.Inspect(file, func(node ast.Node) bool {
		if asgn, ok := node.(*ast.AssignStmt); ok {
			// Check assignments like: err := pkg.Func()
			for i, rhs := range asgn.Rhs {
				if call, ok := rhs.(*ast.CallExpr); ok {
					if isExternalCall(call) {
						// Mark the corresponding LHS as external
						if i < len(asgn.Lhs) {
							if ident, ok := asgn.Lhs[i].(*ast.Ident); ok {
								funcName := getFuncName(call.Fun)
								externalCalls[ident.Name] = &CallInfo{FuncName: funcName}
							}
						}
					}
				}
			}
		}
		return true
	})
}

func isExternalCall(call *ast.CallExpr) bool {
	// Check if this is a call to an external package
	switch call.Fun.(type) {
	case *ast.SelectorExpr:
		// package.Function or receiver.Method
		// For now, consider any selector as potentially external
		return true
	case *ast.Ident:
		// Local function call
		return false
	}
	return false
}

// checkReturns examines return statements and reports unwrapped errors
func checkReturns(file *ast.File, fset *token.FileSet, externalCalls map[string]*CallInfo, ignoreSigs []string, ignoreRegexps []*regexp.Regexp, reports *[]ErrorReport) {
	ast.Inspect(file, func(node ast.Node) bool {
		if ret, ok := node.(*ast.ReturnStmt); ok {
			// Check each return value
			for _, expr := range ret.Results {
				if expr == nil {
					continue
				}

				// Case 1: returning a direct call - return pkg.Func()
				if call, ok := expr.(*ast.CallExpr); ok {
					funcName := getFuncName(call.Fun)
					if funcName != "" && !isIgnored(funcName, ignoreSigs, ignoreRegexps) && isExternalFunc(funcName) {
						pos := fset.Position(call.Pos())
						msg := fmt.Sprintf("error returned from external package is unwrapped: sig: func %s(...) error", funcName)
						*reports = append(*reports, ErrorReport{
							Posn:    fmt.Sprintf("%s:%d:%d", pos.Filename, pos.Line, pos.Column),
							Message: msg,
						})
					}
				}

				// Case 2: returning a variable - return err
				if ident, ok := expr.(*ast.Ident); ok {
					if callInfo, ok := externalCalls[ident.Name]; ok {
						// Check if this function is ignored
						if !isIgnored(callInfo.FuncName, ignoreSigs, ignoreRegexps) {
							pos := fset.Position(ident.Pos())
							msg := fmt.Sprintf("error returned from external package is unwrapped: sig: func %s(...) error", callInfo.FuncName)
							*reports = append(*reports, ErrorReport{
								Posn:    fmt.Sprintf("%s:%d:%d", pos.Filename, pos.Line, pos.Column),
								Message: msg,
							})
						}
					}
				}
			}
		}
		return true
	})
}

func isIgnored(funcName string, ignoreSigs []string, ignoreRegexps []*regexp.Regexp) bool {
	// Check against ignore sigs
	for _, sig := range ignoreSigs {
		if strings.Contains(funcName, sig) {
			return true
		}
	}

	// Check against regexps
	for _, re := range ignoreRegexps {
		if re.MatchString(funcName) {
			return true
		}
	}

	return false
}

func isExternalFunc(funcName string) bool {
	// External means from a package that's not the current package
	// Check if it has a package qualifier
	parts := strings.Split(funcName, ".")
	if len(parts) < 2 {
		// Local function call, not external
		return false
	}

	// If it has a dot, it's a qualified name - consider it external
	return true
}

func getFuncName(expr ast.Expr) string {
	switch e := expr.(type) {
	case *ast.SelectorExpr:
		// e.X.e.Sel
		prefix := getFuncName(e.X)
		if prefix != "" {
			return prefix + "." + e.Sel.Name
		}
		return e.Sel.Name
	case *ast.Ident:
		return e.Name
	}
	return ""
}

func goFileFilter(info os.FileInfo) bool {
	name := info.Name()
	if strings.HasPrefix(name, ".") {
		return false
	}
	return strings.HasSuffix(name, ".go")
}

func loadConfig() (*Config, error) {
	// Try local .wrapcheck.yaml first
	cfg, err := loadYAML(".wrapcheck.yaml")
	if err == nil {
		return cfg, nil
	}

	// Try home directory
	home, err := os.UserHomeDir()
	if err == nil {
		path := filepath.Join(home, ".wrapcheck.yaml")
		cfg, err := loadYAML(path)
		if err == nil {
			return cfg, nil
		}
	}

	// Return defaults
	return &Config{
		IgnoreSigs: []string{
			".Errorf(",
			"errors.New(",
			"errors.Unwrap(",
			"errors.Join(",
			".Wrap(",
			".Wrapf(",
			".WithMessage(",
			".WithMessagef(",
			".WithStack(",
		},
		ReportInternalErrors: true,
	}, nil
}

func loadYAML(path string) (*Config, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}

	cfg := &Config{
		ReportInternalErrors: true,
	}

	// Simple YAML parsing
	scanner := bufio.NewScanner(strings.NewReader(string(data)))
	var currentKey string
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		if strings.HasSuffix(line, ":") {
			currentKey = strings.TrimSuffix(line, ":")
			continue
		}

		if strings.HasPrefix(line, "- ") {
			value := strings.TrimPrefix(line, "- ")
			value = strings.Trim(value, "\"'")

			switch currentKey {
			case "ignoreSigs":
				cfg.IgnoreSigs = append(cfg.IgnoreSigs, value)
			case "extraIgnoreSigs":
				cfg.ExtraIgnoreSigs = append(cfg.ExtraIgnoreSigs, value)
			case "ignoreSigRegexps":
				cfg.IgnoreSigRegexps = append(cfg.IgnoreSigRegexps, value)
			case "ignorePackageGlobs":
				cfg.IgnorePackageGlobs = append(cfg.IgnorePackageGlobs, value)
			case "ignoreInterfaceRegexps":
				cfg.IgnoreInterfaceRegexps = append(cfg.IgnoreInterfaceRegexps, value)
			}
		} else if strings.Contains(line, ":") {
			parts := strings.SplitN(line, ":", 2)
			key := strings.TrimSpace(parts[0])
			value := strings.TrimSpace(parts[1])
			value = strings.Trim(value, "\"'")

			if key == "reportInternalErrors" {
				cfg.ReportInternalErrors = value == "true"
			}
		}
	}

	return cfg, nil
}

func outputJSON(results map[string][]ErrorReport) {
	output := make(map[string]map[string][]ErrorReport)
	for pkg, reports := range results {
		output[pkg] = map[string][]ErrorReport{
			"wrapcheck": reports,
		}
	}
	data, _ := json.MarshalIndent(output, "", "\t")
	fmt.Println(string(data))
}

func outputText(results map[string][]ErrorReport) {
	var keys []string
	for k := range results {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	for _, pkg := range keys {
		for _, report := range results[pkg] {
			fmt.Printf("%s: %s\n", report.Posn, report.Message)

			if *contextFlag >= 0 {
				// Print context lines
				printContext(report.Posn)
			}
		}
	}
}

func printContext(posn string) {
	// Parse position like "/path/to/file.go:12:15"
	parts := strings.Split(posn, ":")
	if len(parts) < 3 {
		return
	}

	filename := parts[0]
	lineNum, _ := strconv.Atoi(parts[1])

	// Read file and print context
	data, err := os.ReadFile(filename)
	if err != nil {
		return
	}

	lines := strings.Split(string(data), "\n")
	start := lineNum - *contextFlag - 1
	if start < 0 {
		start = 0
	}
	end := lineNum + *contextFlag
	if end > len(lines) {
		end = len(lines)
	}

	for i := start; i < end; i++ {
		if i < len(lines) {
			fmt.Printf("\t%d\t%s\n", i+1, lines[i])
		}
	}
}
