func analyzePattern(pattern string) (map[string][]ErrorReport, error) {
	results := make(map[string][]ErrorReport)

	// Handle ./... pattern
	if strings.HasSuffix(pattern, "/...") {
		packages := expandPattern(pattern)
		for _, pkg := range packages {
			reports, _ := analyzeDir(pkg)
			for k, v := range reports {
				results[k] = v
			}
		}
		return results, nil
	}

	reports, err := analyzeDir(pattern)
	if err != nil {
		return nil, err
	}
	return reports, nil
}

func expandPattern(pattern string) []string {
	prefix := strings.TrimSuffix(pattern, "/...")
	if prefix == "." {
		prefix = ""
	}

	var packages []string
	filepath.Walk(".", func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		if !info.IsDir() {
			return nil
		}

		if strings.HasPrefix(filepath.Base(path), ".") && path != "." {
			return filepath.SkipDir
		}

		// Check if this directory contains Go files
		entries, err := os.ReadDir(path)
		if err != nil {
			return nil
		}

		hasGoFiles := false
		for _, e := range entries {
			if !e.IsDir() && strings.HasSuffix(e.Name(), ".go") {
				if *testFlag || !strings.HasSuffix(e.Name(), "_test.go") {
					hasGoFiles = true
					break
				}
			}
		}

		if hasGoFiles {
			if prefix != "" {
				packages = append(packages, filepath.Join(prefix, path))
			} else {
				packages = append(packages, path)
			}
		}

		return nil
	})

	return packages
}

func analyzeDir(dirPath string) (map[string][]ErrorReport, error) {
	results := make(map[string][]ErrorReport)

	// Parse directory
	fset := token.NewFileSet()
	pkgs, err := parser.ParseDir(fset, dirPath, goFileFilter, parser.AllErrors)
	if err != nil {
		return nil, fmt.Errorf("-: %v", err)
	}

	if len(pkgs) == 0 {
		return nil, fmt.Errorf("wrapcheck: %s matched no packages", dirPath)
	}

	// Load configuration
	cfg, _ := loadConfig()

	for pkgName, pkg := range pkgs {
		// Skip test packages if not requested
		if strings.HasSuffix(pkgName, "_test") && !*testFlag {
			continue
		}

		// Analyze the package
		reports := analyzePackageAST(pkg, fset, dirPath, cfg)
		if len(reports) > 0 {
			results[pkgName] = reports
		}
	}

	return results, nil
}

func analyzePackageAST(pkg *ast.Package, fset *token.FileSet, dirPath string, cfg *Config) []ErrorReport {
	var reports []ErrorReport

	// Build ignore patterns
	ignoreSigs := cfg.IgnoreSigs
	if len(ignoreSigs) == 0 && len(cfg.ExtraIgnoreSigs) > 0 {
		ignoreSigs = []string{
			".Errorf(",
			"errors.New(",
			"errors.Unwrap(",
			"errors.Join(",
			".Wrap(",
			".Wrapf(",
			".WithMessage(",
			".WithMessagef(",
			".WithStack(",
		}
	}
	ignoreSigs = append(ignoreSigs, cfg.ExtraIgnoreSigs...)

	// Compile regexps
	var ignoreRegexps []*regexp.Regexp
	for _, pattern := range cfg.IgnoreSigRegexps {
		if re, err := regexp.Compile(pattern); err == nil {
			ignoreRegexps = append(ignoreRegexps, re)
		}
	}

	// Second pass: check returns for external errors
	for _, file := range pkg.Files {
		checkReturns(file, fset, ignoreSigs, ignoreRegexps, &reports)
	}

	return reports
}

// checkReturns examines return statements and reports unwrapped errors
func checkReturns(file *ast.File, fset *token.FileSet, ignoreSigs []string, ignoreRegexps []*regexp.Regexp, reports *[]ErrorReport) {
	// Build a map of variable assignments to track data flow
	varAssignments := make(map[string]*CallInfo) // var name -> where it came from

	// First pass: record all assignments
	ast.Inspect(file, func(node ast.Node) bool {
		if asgn, ok := node.(*ast.AssignStmt); ok {
			for i, rhs := range asgn.Rhs {
				if i >= len(asgn.Lhs) {
					break
				}
				if call, ok := rhs.(*ast.CallExpr); ok {
					if isExternalCall(call) {
						funcName := getFuncName(call.Fun)
						// Record assignment for each LHS that corresponds to this RHS
						if ident, ok := asgn.Lhs[i].(*ast.Ident); ok && ident.Name != "_" {
							varAssignments[ident.Name] = &CallInfo{
								FuncName: funcName,
								CallExpr: call,
							}
						}
					}
				}
			}
		}
		return true
	})

	// Second pass: check returns
	ast.Inspect(file, func(node ast.Node) bool {
		if ret, ok := node.(*ast.ReturnStmt); ok {
			// Check each return value
			for _, expr := range ret.Results {
				if expr == nil {
					continue
				}

				// Case 1: returning a direct call - return pkg.Func()
				if call, ok := expr.(*ast.CallExpr); ok {
					funcName := getFuncName(call.Fun)
					if funcName != "" && !isIgnored(funcName, ignoreSigs, ignoreRegexps) && isExternalFunc(funcName) {
						pos := fset.Position(call.Pos())
						msg := fmt.Sprintf("error returned from external package is unwrapped: sig: func %s(...) error", funcName)
						*reports = append(*reports, ErrorReport{
							Posn:    fmt.Sprintf("%s:%d:%d", pos.Filename, pos.Line, pos.Column),
							Message: msg,
						})
					}
				}

				// Case 2: returning a variable - return err
				if ident, ok := expr.(*ast.Ident); ok {
					if callInfo, ok := varAssignments[ident.Name]; ok {
						// Check if this function is ignored
						if !isIgnored(callInfo.FuncName, ignoreSigs, ignoreRegexps) {
							pos := fset.Position(ident.Pos())
							msg := fmt.Sprintf("error returned from external package is unwrapped: sig: func %s(...) error", callInfo.FuncName)
							*reports = append(*reports, ErrorReport{
								Posn:    fmt.Sprintf("%s:%d:%d", pos.Filename, pos.Line, pos.Column),
								Message: msg,
							})
						}
					}
				}
			}
		}
		return true
	})
}

func isExternalCall(call *ast.CallExpr) bool {
	// Check if this is a call to an external package
	switch call.Fun.(type) {
	case *ast.SelectorExpr:
		// package.Function or receiver.Method
		// For now, consider any selector as potentially external
		return true
	case *ast.Ident:
		// Local function call
		return false
	}
	return false
}

func isIgnored(funcName string, ignoreSigs []string, ignoreRegexps []*regexp.Regexp) bool {
	// Check against ignore sigs
	for _, sig := range ignoreSigs {
		if matchesIgnoreSig(funcName, sig) {
			return true
		}
	}

	// Check against regexps
	for _, re := range ignoreRegexps {
		if re.MatchString(funcName) {
			return true
		}
	}

	return false
}

func matchesIgnoreSig(funcName, sig string) bool {
	// Remove trailing parenthesis from sig
	sig = strings.TrimSuffix(sig, "(")

	// If sig starts with a dot, it's a method pattern like ".Errorf"
	if strings.HasPrefix(sig, ".") {
		// Match if funcName ends with the method name
		return strings.HasSuffix(funcName, sig)
	}

	// Otherwise, it's a full qualified name like "errors.New"
	// Check if funcName contains the sig
	return strings.Contains(funcName, sig)
}

func isExternalFunc(funcName string) bool {
	// External means from a package that's not the current package
	// Check if it has a package qualifier
	parts := strings.Split(funcName, ".")
	if len(parts) < 2 {
		// Local function call, not external
		return false
	}

	// If it has a dot, it's a qualified name - consider it external
	return true
}

func getFuncName(expr ast.Expr) string {
	switch e := expr.(type) {
	case *ast.SelectorExpr:
		// e.X.e.Sel
		prefix := getFuncName(e.X)
		if prefix != "" {
			return prefix + "." + e.Sel.Name
		}
		return e.Sel.Name
	case *ast.Ident:
		return e.Name
	}
	return ""
}

func goFileFilter(info os.FileInfo) bool {
	name := info.Name()
	if strings.HasPrefix(name, ".") {
		return false
	}
	return strings.HasSuffix(name, ".go")
}

func loadConfig() (*Config, error) {
	// Try local .wrapcheck.yaml first
	cfg, err := loadYAML(".wrapcheck.yaml")
	if err == nil {
		return cfg, nil
	}

	// Try home directory
	home, err := os.UserHomeDir()
	if err == nil {
		path := filepath.Join(home, ".wrapcheck.yaml")
		cfg, err := loadYAML(path)
		if err == nil {
			return cfg, nil
		}
	}

	// Return defaults
	return &Config{
		IgnoreSigs: []string{
			".Errorf(",
			"errors.New(",
			"errors.Unwrap(",
			"errors.Join(",
			".Wrap(",
			".Wrapf(",
			".WithMessage(",
			".WithMessagef(",
			".WithStack(",
		},
		ReportInternalErrors: true,
	}, nil
}

func loadYAML(path string) (*Config, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}

	cfg := &Config{
		ReportInternalErrors: true,
	}

	// Simple YAML parsing
	scanner := bufio.NewScanner(strings.NewReader(string(data)))
	var currentKey string
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		if strings.HasSuffix(line, ":") {
			currentKey = strings.TrimSuffix(line, ":")
			continue
		}

		if strings.HasPrefix(line, "- ") {
			value := strings.TrimPrefix(line, "- ")
			value = strings.Trim(value, "\"'")

			switch currentKey {
			case "ignoreSigs":
				cfg.IgnoreSigs = append(cfg.IgnoreSigs, value)
			case "extraIgnoreSigs":
				cfg.ExtraIgnoreSigs = append(cfg.ExtraIgnoreSigs, value)
			case "ignoreSigRegexps":
				cfg.IgnoreSigRegexps = append(cfg.IgnoreSigRegexps, value)
			case "ignorePackageGlobs":
				cfg.IgnorePackageGlobs = append(cfg.IgnorePackageGlobs, value)
			case "ignoreInterfaceRegexps":
				cfg.IgnoreInterfaceRegexps = append(cfg.IgnoreInterfaceRegexps, value)
			}
		} else if strings.Contains(line, ":") {
			parts := strings.SplitN(line, ":", 2)
			key := strings.TrimSpace(parts[0])
			value := strings.TrimSpace(parts[1])
			value = strings.Trim(value, "\"'")

			if key == "reportInternalErrors" {
				cfg.ReportInternalErrors = value == "true"
			}
		}
	}

	return cfg, nil
}

func outputJSON(results map[string][]ErrorReport) {
	output := make(map[string]map[string][]ErrorReport)
	for pkg, reports := range results {
		output[pkg] = map[string][]ErrorReport{
			"wrapcheck": reports,
		}
	}
	data, _ := json.MarshalIndent(output, "", "\t")
	fmt.Println(string(data))
}

func outputText(results map[string][]ErrorReport) {
	var keys []string
	for k := range results {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	for _, pkg := range keys {
		for _, report := range results[pkg] {
			fmt.Printf("%s: %s\n", report.Posn, report.Message)

			if *contextFlag >= 0 {
				// Print context lines
				printContext(report.Posn)
			}
		}
	}
}

func printContext(posn string) {
	// Parse position like "/path/to/file.go:12:15"
	parts := strings.Split(posn, ":")
	if len(parts) < 3 {
		return
	}

	filename := parts[0]
	lineNum, _ := strconv.Atoi(parts[1])

	// Read file and print context
	data, err := os.ReadFile(filename)
	if err != nil {
		return
	}

	lines := strings.Split(string(data), "\n")
	start := lineNum - *contextFlag - 1
	if start < 0 {
		start = 0
	}
	end := lineNum + *contextFlag
	if end > len(lines) {
		end = len(lines)
	}

	for i := start; i < end; i++ {
		if i < len(lines) {
			fmt.Printf("\t%d\t%s\n", i+1, lines[i])
		}
	}
}
